import { Audio } from "#core/ui/audio-base/audio-support.js";
import DialogManager, { DialogBoxOption } from "#core/ui/dialog-box/manager-dialog-box.js";
import { CursorUpdatedEvent, CursorUpdatedEventName } from "#core/ui/input/cursor.js";
import { Focus } from "#core/ui/input/focus-support.js";
import { InputEngineEvent } from "#core/ui/input/input-support.js";
import { PlotCursor, PlotCursorUpdatedEvent, PlotCursorUpdatedEventName } from "#core/ui/input/plot-cursor.js";
import { InterfaceMode } from "#core/ui/interface-modes/interface-modes.js";
import LensManager from "#core/ui/lenses/lens-manager.js";
import NavTray from "#core/ui/navigation-tray/model-navigation-tray.js";
import { ComponentID } from "#core/ui/utilities/utilities-component-id.js";
import { MustGetElement } from "#core/ui/utilities/utilities-dom.js";

import { BuildingPlacementManager } from "#base/ui/building-placement/building-placement-manager.js";
import { City } from "#base/ui/city-selection/city-selection.js";
import { CityZoomer } from "#base/ui/city-zoomer/city-zoomer.js";
import ChoosePlotInterfaceMode from "#base/ui/interface-modes/interface-mode-choose-plot.js";
import { PlaceBuildingV2 } from "#base/ui/place-building/model-place-building-v2.js";
import { ProductionChooserScreen } from "#base/ui/production-chooser/panel-production-chooser.js";

export const TogglePlacementMinMaxEventName = "toggle-placement-min-max" as const;
export class TogglePlacementMinMaxEvent extends CustomEvent<never> {
	constructor() {
		super(TogglePlacementMinMaxEventName);
	}
}

enum HighlightColors {
	okay = 0xc800f2fe,
	good = 0xc81de5b5,
	best = 0xc84db123,
}

interface PlaceBuildingInterfaceModeContext extends InterfaceMode.Context {
	CityID: ComponentID;
	OperationArguments: any;
	IsPurchasing: boolean;
}

/**
 * Handler for INTERFACEMODE_PLACE_BUILDING.
 */
class PlaceBuildingInterfaceMode extends ChoosePlotInterfaceMode {
	private isPurchasing = false;
	private plotOverlay: WorldUI.PlotOverlay | null = null;
	private lastHoveredPlot: PlotIndex = -1;
	private mapFocused = true;

	private uniqueQuarterModelGroup: WorldUI.ModelGroup = WorldUI.createModelGroup("UniqueQuarterModelGroup");
	private OUTER_REGION_OVERLAY_FILTER: WorldUI.ColorFilter = { saturation: 0.1, brightness: 0.3 }; //Semi-opaque dark grey to darken plots outside of the city

	private cursorUpdateListener = this.onCursorUpdated.bind(this);
	private plotCursorUpdatedListener = this.onPlotCursorUpdated.bind(this);

	initialize() {
		const context: PlaceBuildingInterfaceModeContext = this.Context as PlaceBuildingInterfaceModeContext;
		this.isPurchasing = context.IsPurchasing;

		const city: City | null = Cities.get(context.CityID);
		if (!city) {
			console.error(
				"interface-mode-place-building: Unable to find city with CityID: " +
					ComponentID.toLogString(context.CityID),
			);
			return false;
		}
		PlotCursor.plotCursorCoords = city.location;

		let result: OperationResult;
		if (this.isPurchasing) {
			result = Game.CityCommands.canStart(
				context.CityID,
				CityCommandTypes.PURCHASE,
				context.OperationArguments,
				false,
			);
		} else {
			result = Game.CityOperations.canStart(
				context.CityID,
				CityOperationTypes.BUILD,
				context.OperationArguments,
				false,
			);
		}

		const constructible: ConstructibleDefinition | null = GameInfo.Constructibles.lookup(
			context.OperationArguments.ConstructibleType,
		);
		if (!constructible) {
			console.error(
				"interface-mode-place-building: No valid ConstructibleDefinition from ConstructibleType: " +
					context.OperationArguments.ConstructibleType,
			);
			InterfaceMode.switchTo("INTERFACEMODE_CITY_PRODUCTION", { CityID: context.CityID });
			return false;
		}

		BuildingPlacementManager.initializePlacementData(context.CityID);
		BuildingPlacementManager.selectPlacementData(context.CityID, result, constructible);
		LensManager.setActiveLens("fxs-building-placement-lens");
		return true;
	}

	transitionTo(oldMode: InterfaceMode.ModeId, newMode: InterfaceMode.ModeId, context: InterfaceMode.Context) {
		super.transitionTo(oldMode, newMode, context);

		ProductionChooserScreen.shouldReturnToPurchase = this.isPurchasing;

		// Set the building placement cursor
		UI.setCursorByType(UIHTMLCursorTypes.Place);

		this.lastHoveredPlot = -1;

		window.addEventListener(CursorUpdatedEventName, this.cursorUpdateListener);
		window.addEventListener(PlotCursorUpdatedEventName, this.plotCursorUpdatedListener);

		WorldUI.setUnitVisibility(false);

		waitForLayout(() => this.setMapFocused(true));
	}

	transitionFrom(oldMode: InterfaceMode.ModeId, newMode: InterfaceMode.ModeId) {
		//Remove the city hex filter and return to previous zoom level
		WorldUI.popFilter();
		CityZoomer.resetZoom();

		if (this.plotOverlay) {
			this.plotOverlay.clear();
		}
		if (this.uniqueQuarterModelGroup) {
			this.uniqueQuarterModelGroup.clear();
		}

		window.removeEventListener(CursorUpdatedEventName, this.cursorUpdateListener);
		window.removeEventListener(PlotCursorUpdatedEventName, this.plotCursorUpdatedListener);
		WorldUI.setUnitVisibility(true);
		LensManager.setActiveLens("fxs-default-lens");
		super.transitionFrom(oldMode, newMode);
	}

	/** @interface Handler  */
	canEnterMode(parameters: any): boolean {
		const context = parameters as PlaceBuildingInterfaceModeContext;
		return context && context.IsPurchasing != undefined && ComponentID.isValid(context.CityID);
	}

	reset(): void {
		BuildingPlacementManager.reset();
	}

	selectPlot(plot: PlotCoord, _previousPlot: PlotCoord | null): boolean {
		if (
			BuildingPlacementManager.selectedPlotIndex == null ||
			BuildingPlacementManager.selectedPlotIndex != GameplayMap.getIndexFromLocation(plot)
		) {
			BuildingPlacementManager.selectedPlotIndex = GameplayMap.getIndexFromLocation(plot);
			Audio.playSound("data-audio-error-press");
		} else {
			if (this.isPlotProposed) {
				throw new Error("A plot is already being proposed.");
			}
			this.isPlotProposed = true;
			this.proposePlot(
				plot,
				() => {
					this.acceptProposePlotCallback(plot);
				},
				() => (this.isPlotProposed = false),
			);
		}
		return false;
	}

	decorate(overlay: WorldUI.OverlayGroup) {
		const context: PlaceBuildingInterfaceModeContext = this.Context as PlaceBuildingInterfaceModeContext;

		const selectedCity: City | null = Cities.get(context.CityID);
		if (!selectedCity) {
			console.error(
				"interface-mode-place-building: Unable to retrieve city with CityID: " +
					ComponentID.toLogString(context.CityID),
			);
			return;
		}

		CityZoomer.zoomToCity(selectedCity);

		//Darken all plots not in the city
		WorldUI.pushRegionColorFilter(selectedCity.getPurchasedPlots(), {}, this.OUTER_REGION_OVERLAY_FILTER);

		this.plotOverlay = overlay.addPlotOverlay();
		this.plotOverlay.addPlots(BuildingPlacementManager.urbanPlots, { fillColor: HighlightColors.best });
		this.plotOverlay.addPlots(BuildingPlacementManager.developedPlots, { fillColor: HighlightColors.okay });
		this.plotOverlay.addPlots(BuildingPlacementManager.expandablePlots, { fillColor: HighlightColors.good });
		if (!BuildingPlacementManager.isRepairing) {
			for (const plotIndex of BuildingPlacementManager.uniqueQuarterPlots) {
				this.uniqueQuarterModelGroup.addVFXAtPlot(
					"VFX_3dUI_Hex_Highlight_01",
					plotIndex,
					{ x: 0, y: 0, z: 0 },
					{ angle: 0, constants: { Color3: [1, 0.992, 0.62], Alpha1: 1 } },
				);
			}
		}
	}

	undecorate(_overlay: WorldUI.OverlayGroup, _modelGroup: WorldUI.ModelGroup): void {
		this.plotOverlay = null; // parent will remove all overlays from the OverlayGroup
	}

	private onPlotCursorUpdated(event: PlotCursorUpdatedEvent) {
		this.onPlotUpdated(event.detail.plotCoords);
	}

	private onCursorUpdated(event: CursorUpdatedEvent) {
		this.onPlotUpdated(event.detail.plot);
	}

	/**
	 * @override
	 */
	decorateHover(plotCoord: PlotCoord, cursorOverlay: WorldUI.OverlayGroup, cursorModelGroup: WorldUI.ModelGroup) {
		cursorOverlay.clearAll();
		cursorModelGroup.clear();
		cursorModelGroup.addVFXAtPlot("VFX_3dUI_PlotCursor_City_Picker", plotCoord, { x: 0, y: 0, z: 0 });
	}

	private onPlotUpdated(plot: float2 | null) {
		if (plot) {
			const plotIndex = GameplayMap.getIndexFromLocation(plot);

			if (plotIndex != this.lastHoveredPlot) {
				this.lastHoveredPlot = plotIndex;

				// Valid plots are already ready to accept a building
				if (BuildingPlacementManager.isValidPlacementPlot(plotIndex)) {
					UI.setCursorByType(UIHTMLCursorTypes.Place);
				} else {
					UI.setCursorByType(UIHTMLCursorTypes.Default);
				}

				if (plotIndex != BuildingPlacementManager.hoveredPlotIndex) {
					// We also want to select the hovered plot so BuildingPlacementManager
					// knows we're wanting to place the building with the next click
					BuildingPlacementManager.hoveredPlotIndex = plotIndex;
					BuildingPlacementManager.selectedPlotIndex = plotIndex;
				}

				Audio.playSound("data-audio-city-production-placement-focus", "city-actions");
			}
		} else {
			// When the 'cursor-updated' event fires with the cursor on UI, the plot will be null.
			// In this case, we want to reset the cursor to default
			if (UI.getCursorType() != UIHTMLCursorTypes.Default) {
				UI.setCursorByType(UIHTMLCursorTypes.Default);
			}

			BuildingPlacementManager.hoveredPlotIndex = null;
			BuildingPlacementManager.selectedPlotIndex = null;
		}
	}

	private acceptProposePlotCallback(plot: PlotCoord) {
		this.commitPlot(plot);
		const context: PlaceBuildingInterfaceModeContext = this.Context as PlaceBuildingInterfaceModeContext;
		const constructible: ConstructibleDefinition | null = GameInfo.Constructibles.lookup(
			context.OperationArguments.ConstructibleType,
		);
		const constructibleType: string = constructible ? "-" + constructible.ConstructibleType : "";
		const selectedCityID: ComponentID | null = UI.Player.getHeadSelectedCity(); // May be null if placing results in deselecting city
		if (selectedCityID && ComponentID.isValid(selectedCityID)) {
			const isEmptyQueue: boolean = City.isQueueEmpty(selectedCityID);
			if (isEmptyQueue || this.isPurchasing) {
				UI.sendAudioEvent("placement-activate" + constructibleType);
			} else {
				UI.sendAudioEvent("placement-queue" + constructibleType);
			}

			if (!this.isPurchasing && isEmptyQueue && !Configuration.getUser().isProductionPanelStayOpen) {
				UI.Player.deselectAllCities();
				InterfaceMode.switchToDefault();
			} else {
				InterfaceMode.switchTo("INTERFACEMODE_CITY_PRODUCTION", { CityID: selectedCityID });
			}
		} else {
			console.warn(
				"Attempt to jump back to the city product (hopefully that was the previous UI mode) but no city is selected!",
			);
			InterfaceMode.switchToDefault();
		}
	}

	proposePlot(plot: PlotCoord, accept: () => void, reject: () => void) {
		const plotIndex = GameplayMap.getIndexFromLocation(plot);
		// We want to catch if there are potential unique quarter plots
		// There are two cases here:
		// We try and place a unique quarter building on a non-suggested plot
		// We try and place a regular building on a unique quarter plot
		if (
			!BuildingPlacementManager.currentConstructible?.ExistingDistrictOnly &&
			((BuildingPlacementManager.uniqueQuarterPlots.length > 0 &&
				!BuildingPlacementManager.uniqueQuarterPlots.includes(plotIndex)) ||
				(BuildingPlacementManager.uniqueQuarterPlots.length <= 0 &&
					BuildingPlacementManager.potentialUniqueQuarterPlots.map((a) => a.plotID).includes(plotIndex)))
		) {
			const acceptCallback = () => {
				accept();
			};

			const cancelCallback = () => {
				this.setMapFocused(true);
				reject();
			};

			const okOption: DialogBoxOption = {
				actions: ["accept"],
				label: "LOC_GENERIC_OK",
				callback: acceptCallback,
			};

			const cancelOption: DialogBoxOption = {
				actions: ["cancel", "keyboard-escape", "mousebutton-right"],
				label: "LOC_GENERIC_CANCEL",
				callback: cancelCallback,
			};

			if (!BuildingPlacementManager.currentConstructible) {
				console.error(
					"interface-mode-place-building: No valid currentConstructible variable in BuildingPlacementManager!",
				);
				reject();
				return;
			}

			let currentQuarterDef = BuildingPlacementManager.currentQuarter ?? undefined;
			if (!currentQuarterDef) {
				currentQuarterDef = BuildingPlacementManager.potentialUniqueQuarterPlots.find(
					(a) => a.plotID == plotIndex,
				)?.uniqueQuarterDef;
			}
			if (!currentQuarterDef) {
				console.error(
					"interface-mode-place-building: No valid current Quarter definition found! But one is expected!",
				);
				reject();
				return;
			}

			const body = Locale.stylize(
				"LOC_BUILDING_PLACEMENT_UNIQUE_QUARTER_BLOCKER_BODY",
				BuildingPlacementManager.currentConstructible.Name,
				currentQuarterDef.Name,
			);

			const options: DialogBoxOption[] = [okOption, cancelOption];
			NavTray.clear();
			DialogManager.createDialog_MultiOption({
				body: body,
				title: "LOC_BUILDING_PLACEMENT_UNIQUE_QUARTER_BLOCKER",
				options: options,
				canClose: false,
			});
		}
		//Urban plots and undeveloped plots are ready to accept the building placement
		else if (
			BuildingPlacementManager.urbanPlots.find((p) => p == plotIndex) ||
			BuildingPlacementManager.expandablePlots.find((p) => p == plotIndex)
		) {
			accept();
		}
		//Building over a developed plot requires confirmation to replace the improvement on that plot
		else if (BuildingPlacementManager.developedPlots.find((p) => p == plotIndex)) {
			const acceptCallback = () => {
				accept();
			};

			const cancelCallback = () => {
				this.setMapFocused(true);
				reject();
			};

			if (!BuildingPlacementManager.currentConstructible) {
				console.error(
					"interface-mode-place-building: No valid currentConstructible variable in BuildingPlacementManager!",
				);
				reject();
				return;
			}
			const oldImprovementNameKey: string = this.getImprovementNameKey(plot);
			const okOption: DialogBoxOption = {
				actions: ["accept"],
				label: "LOC_GENERIC_OK",
				callback: acceptCallback,
			};

			const cancelOption: DialogBoxOption = {
				actions: ["cancel", "keyboard-escape", "mousebutton-right"],
				label: "LOC_GENERIC_CANCEL",
				callback: cancelCallback,
			};

			const options: DialogBoxOption[] = [okOption, cancelOption];
			if (BuildingPlacementManager.currentConstructible.ConstructibleClass == "WONDER") {
				const body: string =
					oldImprovementNameKey != ""
						? Locale.compose(
								"LOC_BUILDING_PLACEMENT_REMOVE_IMPOVEMENT_BODY",
								oldImprovementNameKey,
								BuildingPlacementManager.currentConstructible.Name,
							)
						: Locale.compose(
								"LOC_BUILDING_PLACEMENT_REMOVE_GENERIC_IMPOVEMENT_BODY",
								BuildingPlacementManager.currentConstructible.Name,
							);

				NavTray.clear();
				DialogManager.createDialog_MultiOption({
					body: body,
					title: "LOC_BUILDING_PLACEMENT_REMOVE_IMPOVEMENT",
					options: options,
					canClose: false,
				});
			} else {
				const replacedConstructibleType: number = MapConstructibles.getReplaceableConstructible(plot.x, plot.y);

				if (replacedConstructibleType == -1) {
					const body: string =
						oldImprovementNameKey != ""
							? Locale.compose(
									"LOC_BUILDING_PLACEMENT_CREATE_URBAN_TILE_REMOVE_IMPROVEMENT",
									oldImprovementNameKey,
									BuildingPlacementManager.currentConstructible.Name,
								)
							: Locale.compose(
									"LOC_BUILDING_PLACEMENT_CREATE_URBAN_TILE_BODY",
									BuildingPlacementManager.currentConstructible.Name,
								);

					NavTray.clear();
					DialogManager.createDialog_MultiOption({
						body: body,
						title: "LOC_BUILDING_PLACEMENT_CREATE_URBAN_TILE",
						options: options,
						canClose: false,
					});
				} else {
					const body: string = Locale.compose(
						"LOC_BUILDING_PLACEMENT_REPLACE_BUILDING_BODY",
						BuildingPlacementManager.currentConstructible.Name,
					);

					NavTray.clear();
					DialogManager.createDialog_MultiOption({
						body: body,
						title: "LOC_BUILDING_PLACEMENT_REPLACE_BUILDING",
						options: options,
						canClose: false,
					});
				}
			}
		} else {
			// Allow player to propose another plot
			this.isPlotProposed = false;
		}
	}

	private getImprovementNameKey(plotCoord: PlotCoord): Readonly<string> {
		const constructibles = MapConstructibles.getConstructibles(plotCoord.x, plotCoord.y);

		// only one improvement is possible per tile, so find it if there is one
		for (const constructible of constructibles) {
			const instance = Constructibles.getByComponentID(constructible);
			if (instance) {
				const info = GameInfo.Constructibles.lookup(instance.type);
				if (info && info.ConstructibleClass == "IMPROVEMENT") {
					return info.Name;
				}
			}
		}

		console.error(
			`interface-mode-place-building: Failed to find improvement where one should exist at ${plotCoord}`,
		);
		return "";
	}

	commitPlot(plot: PlotCoord) {
		const context = this.Context as PlaceBuildingInterfaceModeContext;
		const cityID = context.CityID;
		const operationArgs = context.OperationArguments;
		operationArgs.X = plot.x;
		operationArgs.Y = plot.y;

		let result: OperationResult | null = null;
		if (this.isPurchasing) {
			result = Game.CityCommands.canStart(cityID, CityCommandTypes.PURCHASE, operationArgs, false);
			if (result.Success) {
				Game.CityCommands.sendRequest(cityID, CityCommandTypes.PURCHASE, operationArgs);
			} else {
				// Allow the player to propose another plot
				this.isPlotProposed = false;
			}
		} else {
			result = Game.CityOperations.canStart(cityID, CityOperationTypes.BUILD, operationArgs, false);
			if (result.Success) {
				Game.CityOperations.sendRequest(cityID, CityOperationTypes.BUILD, operationArgs);
			} else {
				// Allow the player to propose another plot
				this.isPlotProposed = false;
			}
		}

		if (result.Success) {
			engine.trigger("CommitPlotBuildingPlacement");
		}
	}

	updateNavTray() {
		NavTray.clear();

		if (this.mapFocused) {
			if (PlaceBuildingV2.showExpandedView) {
				NavTray.addOrUpdateNotification("LOC_BUILDING_PLACEMENT_PRESS_SPACE_HIDE_DETAILS");
			} else {
				NavTray.addOrUpdateNotification("LOC_BUILDING_PLACEMENT_PRESS_SPACE_SHOW_DETAILS");
			}
			NavTray.addOrUpdateNextAction("LOC_UI_FOCUS_WORLD");
		} else {
			NavTray.addOrUpdateShellAction2("LOC_UI_FOCUS_PLACEMENT_INFO");
		}

		NavTray.addOrUpdateGenericCancel();
	}

	setMapFocused(isMapFocused: boolean) {
		this.mapFocused = isMapFocused;
		this.updateNavTray();

		if (this.mapFocused) {
			Input.setActiveContext(InputContext.World);
			Audio.playSound("data-audio-hero-press");
		} else {
			Input.setActiveContext(InputContext.Shell);
			const placeBuildingPanel = MustGetElement("panel-place-building-v2", document);
			Audio.playSound("data-audio-hero-press");

			if (placeBuildingPanel) {
				Focus.setContextAwareFocus(placeBuildingPanel, placeBuildingPanel);
			}
		}
	}

	handleInput(inputEvent: InputEngineEvent): boolean {
		if (inputEvent.detail.status != InputActionStatuses.FINISH) {
			return true;
		}

		if (inputEvent.isCancelInput() || inputEvent.detail.name == "sys-menu") {
			const selectedCityID: ComponentID | null = UI.Player.getHeadSelectedCity(); // May be null if placing results in deselecting city
			if (selectedCityID && ComponentID.isValid(selectedCityID)) {
				InterfaceMode.switchTo("INTERFACEMODE_CITY_PRODUCTION", { CityID: selectedCityID });

				inputEvent.stopPropagation();
				inputEvent.preventDefault();
				return false;
			}
		}

		const eventToLookFor = this.mapFocused ? "next-action" : "shell-action-2";
		if (inputEvent.detail.name == eventToLookFor) {
			this.setMapFocused(!this.mapFocused);
			inputEvent.stopPropagation();
			inputEvent.preventDefault();

			return false;
		}

		if (inputEvent.detail.name == "unit-skip-turn" || inputEvent.detail.name == "notification") {
			window.dispatchEvent(new TogglePlacementMinMaxEvent());
			this.updateNavTray();
			inputEvent.stopPropagation();
			inputEvent.preventDefault();
			return false;
		}

		return true;
	}
}

InterfaceMode.addHandler("INTERFACEMODE_PLACE_BUILDING", new PlaceBuildingInterfaceMode());
